-- 3. Seed Botanical Products (Linked to Admin/Sellers via userId)
INSERT INTO products (
    id, title, "scientificName", description, price, stock, placement, "lightRequirement",
    "wateringFrequency", "careLevel", "isPetFriendly", humidity, "potSize", category, images, "userId", "createdAt", "updatedAt"
) VALUES
('b1111111-1111-4111-8111-111111111111', 'Monstera Deliciosa', 'Monstera deliciosa', 'A stunning tropical icon known for its vibrant glossy heart-shaped leaves that develop natural perforations (fenestrations) as it matures. An architectural centerpiece that thrives indoors and purifies living spaces.', 48, 15, 'INDOOR', 'INDIRECT_BRIGHT', 'MODERATE', 'EASY', false, '60-80%', '22cm', 'Houseplants', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335217/planto/products/monstera_deliciosa.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b2222222-2222-4222-8222-222222222222', 'Fiddle Leaf Fig', 'Ficus lyrata', 'Celebrated for its majestic, violin-shaped broad leaves and deep emerald luster. An interior designer favorite that makes an imposing sculptural statement in brightly lit corners and high-ceiling rooms.', 72, 8, 'INDOOR', 'INDIRECT_BRIGHT', 'MODERATE', 'MODERATE', false, '50-70%', '26cm', 'Indoor Trees', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335219/planto/products/fiddle_leaf_fig.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b3333333-3333-4333-8333-333333333333', 'Snake Plant Laurentii', 'Sansevieria trifasciata ''Laurentii''', 'An architectural powerhouse featuring upright sword-shaped succulent leaves edged with vibrant golden-yellow bands. Renowned for NASA-proven air purification and nearly indestructible resilience.', 34, 25, 'BOTH', 'LOW_LIGHT', 'LOW', 'EASY', false, '30-50%', '18cm', 'Air Purifying', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335222/planto/products/snake_plant_laurentii.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b4444444-4444-4444-8444-444444444444', 'Peace Lily', 'Spathiphyllum wallisii', 'Elegant tropical perennial featuring glossy dark green foliage and magnificent pure white flowering spathes. Signals its thirst by gently drooping, making it one of the easiest and most communicative flowering houseplants.', 38, 20, 'INDOOR', 'LOW_LIGHT', 'HIGH', 'EASY', false, '60-80%', '19cm', 'Flowering', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335223/planto/products/peace_lily.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b5555555-5555-4555-8555-555555555555', 'Calathea Orbifolia', 'Goeppertia orbifolia', 'A rare botanical gem showcasing oversized, orb-like leaves adorned with delicate metallic silver and emerald pinstripes. A pet-friendly, non-toxic prayer plant that folds its foliage gracefully at nightfall.', 42, 12, 'INDOOR', 'INDIRECT_BRIGHT', 'MODERATE', 'MODERATE', true, '65-85%', '17cm', 'Pet-Friendly', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335225/planto/products/calathea_orbifolia.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b6666666-6666-4666-8666-666666666666', 'ZZ Plant ''Raven''', 'Zamioculcas zamiifolia ''Raven''', 'An exotic cultivar prized for its glossy feathered foliage that emerges bright lime green and matures into an opulent, obsidian-black shade. Extremely drought-tolerant and thrives even in low-light conditions.', 52, 14, 'INDOOR', 'LOW_LIGHT', 'LOW', 'EASY', false, '40-60%', '16cm', 'Rare & Exotic', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335226/planto/products/zz_plant__raven_.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b7777777-7777-4777-8777-777777777777', 'Bird of Paradise', 'Strelitzia nicolai', 'The quintessential tropical statement plant boasting enormous banana-like leaves arranged in a grand sculptural fan. Brings an instant luxury resort ambiance to any bright, sun-drenched interior.', 85, 6, 'INDOOR', 'DIRECT_SUN', 'MODERATE', 'MODERATE', false, '60-70%', '30cm', 'Tropical Giants', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335228/planto/products/bird_of_paradise.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b8888888-8888-4888-8888-888888888888', 'Boston Fern', 'Nephrolepis exaltata', 'A timeless Victorian classic with lush arching fronds composed of delicate, feathery leaflets. Safe for curious cats and dogs, and acts as a natural room humidifier and air purifier.', 29, 22, 'INDOOR', 'INDIRECT_BRIGHT', 'HIGH', 'EASY', true, '70-90%', '18cm', 'Hanging Plants', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335229/planto/products/boston_fern.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('b9999999-9999-4999-8999-999999999999', 'String of Pearls', 'Senecio rowleyanus', 'A mesmerizing trailing succulent with cascading strings of plump, pea-shaped beads designed to store water in arid climates. Creates a dramatic waterfall effect when placed on high shelves or hanging macrame.', 26, 24, 'INDOOR', 'INDIRECT_BRIGHT', 'LOW', 'MODERATE', false, '30-50%', '14cm', 'Succulents & Cacti', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335231/planto/products/string_of_pearls.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('baaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', 'Bonsai Ficus Ginseng', 'Ficus microcarpa ''Ginseng''', 'A living work of art featuring thick, sculptural exposed aerial roots reminiscent of ginseng tubers, crowned with a dense canopy of glossy oval leaves. Highly durable and perfect for bonsai beginners and zen decor.', 64, 10, 'INDOOR', 'INDIRECT_BRIGHT', 'MODERATE', 'EASY', false, '50-70%', '20cm', 'Bonsai', ARRAY['https://res.cloudinary.com/dmohzjxxd/image/upload/v1792335232/planto/products/bonsai_ficus_ginseng.jpg'], 'a1111111-1111-4111-8111-111111111111', NOW(), NOW());

-- 4. Seed Botanical Product Reviews
INSERT INTO reviews (id, rating, comment, "productId", "userId", "createdAt", "updatedAt") VALUES
('c1111111-1111-4111-8111-111111111111', 5, 'Arrived in perfect condition with vibrant fenestrated leaves! Looks like a piece of art in our living room.', 'b1111111-1111-4111-8111-111111111111', 'a3333333-3333-4333-8333-333333333333', NOW(), NOW()),
('c2222222-2222-4222-8222-222222222222', 5, 'Healthy roots, beautiful emerald foliage. Exceeded my expectations for online plant shopping.', 'b2222222-2222-4222-8222-222222222222', 'a3333333-3333-4333-8333-333333333333', NOW(), NOW()),
('c3333333-3333-4333-8333-333333333333', 5, 'Indestructible! Tolerates low light and purifies the bedroom air noticeably.', 'b3333333-3333-4333-8333-333333333333', 'a1111111-1111-4111-8111-111111111111', NOW(), NOW()),
('c4444444-4444-4444-8444-444444444444', 4, 'Flowering right out of the box, communicative when it needs water. Very calming plant.', 'b4444444-4444-4444-8444-444444444444', 'a2222222-2222-4222-8222-222222222222', NOW(), NOW()),
('c5555555-5555-4555-8555-555555555555', 5, 'Safe for my cat and the silver stripes on the leaves look unreal in morning light!', 'b5555555-5555-4555-8555-555555555555', 'a3333333-3333-4333-8333-333333333333', NOW(), NOW());
